<!--
 * WebAuthn/Passkey 管理页面 — 用户端生物识别凭证管理
 *
 * @path apps\userinfo-web\src\views\webauthn\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * WebAuthn/Passkey 管理（用户端凭证管理页）
 * <p>展示当前登录用户已注册的 WebAuthn 凭证列表，支持查看和删除操作，
 * 消费后端契约 WebAuthnController
 * （src/api/webAuthn.ts，auto-generated by bash/gen-contract.py）：
 * listCredentials() 获取当前用户凭证列表，deleteCredential() 删除凭证。
 * <p>注册功能仅展示简化说明，完整流程需配合浏览器 WebAuthn API。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import { Page } from '@ydsz/common-ui';

import {
  ElButton,
  ElCard,
  ElDescriptions,
  ElDescriptionsItem,
  ElDialog,
  ElEmpty,
  ElIcon,
  ElMessage,
  ElMessageBox,
  ElTag,
  ElTimeline,
  ElTimelineItem,
} from 'element-plus';
import { computed, onMounted, ref } from 'vue';
import { useI18n } from 'vue-i18n';

import { createLogger } from '@ydsz-core/shared/utils';

import { deleteCredential, listCredentials } from '#/api/webAuthn';
import type { WebAuthnCredentialVO } from '#/api/models';

defineOptions({ name: 'WebAuthnManagement' });

const logger = createLogger('userinfo-webauthn');
const { t } = useI18n();

/** 凭证列表数据 */
const credentials = ref<WebAuthnCredentialVO[]>([]);
const loading = ref(false);

/** 注册说明弹窗显示 */
const registerDialogVisible = ref(false);

/** 凭证详情弹窗显示 */
const detailDialogVisible = ref(false);

/** 当前查看详细凭证 */
const selectedCredential = ref<WebAuthnCredentialVO | null>(null);

/** 凭证类型中文映射 */
const credentialTypeLabels: Record<string, string> = {
  'public-key': '公钥凭证',
};

/** 格式化凭证 ID 截取展示 */
function formatCredentialId(id?: string): string {
  if (!id) return '-';
  if (id.length <= 24) return id;
  return `${id.slice(0, 12)}...${id.slice(-8)}`;
}

/** 格式化日期时间展示 */
function formatDateTime(dt?: string): string {
  if (dt) {
    return new Date(dt).toLocaleString('zh-CN', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
    });
  }
  return '-';
}

/** 加载凭证列表 */
async function loadCredentials() {
  loading.value = true;
  try {
    credentials.value = (await listCredentials()) ?? [];
  } catch (error) {
    logger.warn('加载 WebAuthn 凭证列表失败: {}', error);
    credentials.value = [];
  } finally {
    loading.value = false;
  }
}

onMounted(loadCredentials);

/** 打开凭证详情弹窗 */
function handleViewDetail(cred: WebAuthnCredentialVO) {
  selectedCredential.value = cred;
  detailDialogVisible.value = true;
}

/** 删除凭证操作 */
async function handleDelete(cred: WebAuthnCredentialVO) {
  if (!cred.credentialId) return;
  try {
    await ElMessageBox.confirm(
      '确认删除该 Passkey 凭证？删除后将无法使用该凭证登录。',
      '确认删除',
      { type: 'warning' },
    );
  } catch {
    return;
  }
  try {
    await deleteCredential({ credentialId: cred.credentialId });
    ElMessage.success('凭证已删除');
    loadCredentials();
  } catch (error) {
    logger.warn('删除 WebAuthn 凭证失败: {}', error);
  }
}

/** 注册流程说明步骤 */
const registrationSteps = [
  {
    title: '点击注册按钮',
    description: '点击下方"注册 Passkey"按钮获取注册选项',
    timestamp: '',
  },
  {
    title: '浏览器弹出验证',
    description: '浏览器会弹出系统验证面板（Windows Hello、Touch ID 等）',
    timestamp: '',
  },
  {
    title: '完成身份验证',
    description: '按提示完成指纹/面部识别或安全密钥验证',
    timestamp: '',
  },
  {
    title: '注册成功',
    description: '凭证已保存，下次可使用该方式无密码登录',
    timestamp: '',
  },
];

const credentialCount = computed(() => credentials.value.length);
</script>

<template>
  <Page auto-content-height>
    <div class="webauthn-management">
      <!-- 顶部概览卡片 -->
      <ElCard shadow="never" class="mb-4">
        <div class="flex items-center justify-between">
          <div class="flex items-center gap-3">
            <ElIcon :size="24" class="text-blue-500">
              <svg
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                stroke-width="2"
              >
                <path
                  d="M12 2a10 10 0 0 1 10 10 10 10 0 0 1-10 10A10 10 0 0 1 2 12 10 10 0 0 1 12 2m0 2a8 8 0 0 0-8 8 8 8 0 0 0 8 8 8 8 0 0 0 8-8 8 8 0 0 0-8-8m0 2a6 6 0 0 1 6 6c0 1.77-.77 3.36-2 4.46V12a4 4 0 0 0-8 0v4.46A5.98 5.98 0 0 1 6 12a6 6 0 0 1 6-6m0 2a4 4 0 0 0-4 4v3a4 4 0 0 0 8 0v-3a4 4 0 0 0-4-4z"
                />
              </svg>
            </ElIcon>
            <div>
              <h3 class="text-lg font-semibold">Passkey 管理</h3>
              <p class="text-sm text-gray-500">
                管理您的生物识别登录凭证，共 {{ credentialCount }} 个凭证
              </p>
            </div>
          </div>
          <div class="flex gap-2">
            <ElButton type="primary" @click="registerDialogVisible = true">
              注册 Passkey
            </ElButton>
            <ElButton :loading="loading" @click="loadCredentials">刷新</ElButton>
          </div>
        </div>
      </ElCard>

      <!-- 凭证列表 -->
      <ElCard shadow="never">
        <template #header>
          <span class="font-medium">已注册凭证</span>
        </template>

        <!-- 空状态 -->
        <ElEmpty
          v-if="!loading && credentials.length === 0"
          description="尚未注册任何 Passkey 凭证"
          :image-size="100"
        >
          <template #description>
            <p class="text-gray-500">
              注册 Passkey 后可使用生物识别（指纹/面部）或安全密钥快速登录
            </p>
          </template>
          <ElButton type="primary" @click="registerDialogVisible = true">
            立即注册
          </ElButton>
        </ElEmpty>

        <!-- 凭证列表 -->
        <div v-else class="space-y-3">
          <div
            v-for="cred in credentials"
            :key="cred.credentialId"
            class="flex items-center justify-between p-4 border border-gray-200 rounded-lg hover:border-blue-300 hover:shadow-sm transition-all"
          >
            <div class="flex items-center gap-3">
              <ElIcon :size="28" class="text-gray-400">
                <svg
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  stroke-width="1.5"
                >
                  <rect x="3" y="6" width="18" height="14" rx="2" />
                  <path d="M3 10h18" />
                  <circle cx="8" cy="14" r="1" fill="currentColor" />
                  <circle cx="12" cy="14" r="1" fill="currentColor" />
                  <circle cx="16" cy="14" r="1" fill="currentColor" />
                </svg>
              </ElIcon>
              <div>
                <div class="flex items-center gap-2">
                  <span class="font-medium">{{
                    cred.displayName || '未命名凭证'
                  }}</span>
                  <ElTag size="small" type="info">{{
                    credentialTypeLabels[cred.credentialType ?? ''] ||
                    cred.credentialType ||
                    '凭证'
                  }}</ElTag>
                </div>
                <div class="text-xs text-gray-400 mt-1">
                  ID: {{ formatCredentialId(cred.credentialId) }}
                </div>
              </div>
            </div>
            <div class="flex items-center gap-4 text-sm text-gray-500">
              <div class="text-right">
                <div>注册于: {{ formatDateTime(cred.registeredAt) }}</div>
                <div class="mt-0.5">
                  最后使用: {{ formatDateTime(cred.lastUsedAt) }}
                </div>
              </div>
              <div class="flex gap-1">
                <ElButton
                  size="small"
                  link
                  type="primary"
                  @click="handleViewDetail(cred)"
                >
                  详情
                </ElButton>
                <ElButton
                  size="small"
                  link
                  type="danger"
                  @click="handleDelete(cred)"
                >
                  删除
                </ElButton>
              </div>
            </div>
          </div>
        </div>
      </ElCard>

      <!-- 注册说明弹窗 -->
      <ElDialog
        v-model="registerDialogVisible"
        title="注册 Passkey"
        width="560px"
      >
        <div class="mb-4">
          <p class="text-gray-600">
            注册 Passkey 后，您可以使用设备的生物识别功能（如 Windows Hello、Apple
            Touch ID/Face ID）或安全密钥（YubiKey
            等）快速、安全地登录系统。
          </p>
        </div>

        <ElTimeline>
          <ElTimelineItem
            v-for="(step, index) in registrationSteps"
            :key="step.title ?? index"
            :hollow="index > 0"
          >
            <div class="font-medium">{{ step.title }}</div>
            <div class="text-sm text-gray-500 mt-1">
              {{ step.description }}
            </div>
          </ElTimelineItem>
        </ElTimeline>

        <template #footer>
          <ElButton @click="registerDialogVisible = false">关闭</ElButton>
          <ElButton type="primary" disabled>
            注册 Passkey（需在支持设备上操作）
          </ElButton>
        </template>
      </ElDialog>

      <!-- 凭证详情弹窗 -->
      <ElDialog v-model="detailDialogVisible" title="凭证详情" width="500px">
        <ElDescriptions v-if="selectedCredential" :column="1" border>
          <ElDescriptionsItem label="凭证 ID">
            <span class="text-xs break-all">{{
              selectedCredential.credentialId
            }}</span>
          </ElDescriptionsItem>
          <ElDescriptionsItem label="显示名称">
            {{ selectedCredential.displayName || '-' }}
          </ElDescriptionsItem>
          <ElDescriptionsItem label="凭证类型">
            {{ selectedCredential.credentialType || '-' }}
          </ElDescriptionsItem>
          <ElDescriptionsItem label="AAGUID">
            <span class="text-xs">{{ selectedCredential.aaguid || '-' }}</span>
          </ElDescriptionsItem>
          <ElDescriptionsItem label="签名计数">
            {{ selectedCredential.signCount ?? 0 }}
          </ElDescriptionsItem>
          <ElDescriptionsItem label="注册时间">
            {{ formatDateTime(selectedCredential.registeredAt) }}
          </ElDescriptionsItem>
          <ElDescriptionsItem label="最后使用">
            {{ formatDateTime(selectedCredential.lastUsedAt) }}
          </ElDescriptionsItem>
        </ElDescriptions>
        <template #footer>
          <ElButton @click="detailDialogVisible = false">{{
            t('page.close')
          }}</ElButton>
        </template>
      </ElDialog>
    </div>
  </Page>
</template>

<style scoped>
.webauthn-management {
  padding: 16px;
}
</style>
